cd /workspace && python3 - <<'EOF'
import urllib.request, re
base='http://127.0.0.1:5173/'
seen=set(); bad=[]; q=['/resources/js/app.ts','/resources/js/pages/MainPage.vue']
while q:
    p=q.pop()
    if p in seen: continue
    seen.add(p)
    try:
        body=urllib.request.urlopen(base+p.lstrip('/'),timeout=30).read().decode('utf-8','ignore')
    except urllib.error.HTTPError as e:
        bad.append((p,e.code)); continue
    except Exception as e:
        bad.append((p,str(e))); continue
    for m in re.findall(r'from\s*["\']([^"\']+)["\']', body)+re.findall(r'import\s*\(\s*["\']([^"\']+)["\']', body):
        if m.startswith('/') and '/node_modules/.vite/deps' not in m and not m.startswith('/@'):
            q.append(m)
print("modules fetched:",len(seen))
for s in sorted(seen): print(" ",s)
print("broken:",bad)
EOF

